-- Seed data DUMMY modul School Culture untuk Yayasan Pendidikan Sekolah Fammi (YPS-FAMMI):
-- 150 staf di enam unit, periode 2026-07, lengkap dengan laporan individu tiap staf,
-- agregat lembaga per unit, briefing, sembilan tindak lanjut, plus akun login kelompok dan
-- akun perorangan.
--
-- SEMUA ANGKA, NAMA, DAN JAWABAN ESAI DI BAWAH REKAAN. Tidak ada satu pun baris yang berasal
-- dari sekolah sungguhan. Berkas ini dibangkitkan generator deterministik (seed 20260826),
-- bukan diketik tangan, supaya angka agregat sc_lembaga benar-benar turunan dari jawaban 150
-- baris sc_personal, bukan angka yang ditulis terpisah:
--   budaya lembaga    = rata-rata mean jawaban per tipe, skala 1-5 dikonversi persen (x/5*100)
--   profil organisasi = rata-rata 4 tipe per dimensi, rumus persen yang sama
--   kesejahteraan     = rata-rata butir b1-b13 per subdimensi, rumus persen yang sama
--   t_gambaran/t_harapan level personal = T-score (mean 50, sd 10) terhadap sebaran 150 orang;
--     harapan memakai mean/sd milik gambaran supaya gap punya arti, bukan dua skala terpisah.
--
-- LIMA BAGIAN, JALANKAN BERURUTAN (nomor timestamp sudah mengurutkannya sendiri):
--   1 personal  -- sekolah, entitlement, 150 baris sc_personal (bagian ini juga yang bersih-bersih)
--   2 lembaga   -- sc_lembaga (agregat + 6 unit), briefing, 9 tindak lanjut
--   3 individu  -- sc_hasil responden 1-75
--   4 individu  -- sc_hasil responden 76-150
--   5 akun      -- akun Yayasan + 150 akun Karyawan
-- Dipecah lima karena satu berkas gabungan berukuran 2 MB, terlalu besar untuk ditempel ke
-- SQL Editor Supabase. Idempoten: bagian 1 membuang seluruh jejak YPS-FAMMI lebih dulu,
-- jadi menjalankan ulang kelimanya dari awal selalu aman.
--
-- Status: briefing, tindak_lanjut, dan sc_hasil langsung 'disetujui'. Ini seed demo yang
-- disetujui pemilik produk saat dibuat, bukan jalur yang melewati gerbang persetujuan
-- (CLAUDE.md butir 6). Jalur generate Gemini/Excel tetap masuk 'menunggu_persetujuan' seperti
-- biasa dan tidak disentuh migration ini.

-- ═══ BAGIAN 1 dari 5: sekolah + 150 baris sc_personal ═══

-- ── 1.1 Bersih-bersih (urutan mengikuti arah foreign key) ─────────────────────────────
-- profiles dihapus sebelum sc_personal karena profiles.sc_responden_id menunjuk ke sana,
-- dan auth.users dihapus sesudah profiles karena profiles.id menunjuk ke auth.users.
delete from public.sc_komitmen where sc_personal_id in (select id from public.sc_personal where sekolah_id = 'YPS-FAMMI');
delete from public.sc_feedback where sekolah_id = 'YPS-FAMMI';
delete from public.sc_hasil where sekolah_id = 'YPS-FAMMI';
delete from public.profiles where school_id = 'YPS-FAMMI';
delete from auth.users where email like 'ypsstaf%@fammi.internal' or email = 'ypsfammi@fammi.internal';
delete from public.sc_personal where sekolah_id = 'YPS-FAMMI';
delete from public.sc_lembaga where sekolah_id = 'YPS-FAMMI';
delete from public.tindak_lanjut where sekolah_id = 'YPS-FAMMI' and modul = 'sc';
delete from public.briefing where sekolah_id = 'YPS-FAMMI' and modul = 'sc';

-- ── 1.2 Sekolah + entitlement ─────────────────────────────────────────────────────────
-- Satu baris schools mewakili seluruh yayasan, enam unit dibedakan lewat kolom `unit` di
-- sc_lembaga/sc_personal. Pola yang sama dipakai Yayasan Pendidikan Fammi (modul LW) dan
-- Sekolah Islam Athirah (modul PA): satu login, banyak unit. Ini entitas BERBEDA dari
-- YP-FAMMI yang sudah ada; id, nama, dan modulnya sendiri.
values ('YPS-FAMMI', 'Yayasan Pendidikan Sekolah Fammi', 'Semua Jenjang')
on conflict (id) do update set nama = excluded.nama, jenjang = excluded.jenjang;

values ('YPS-FAMMI', 'sc', true)
on conflict (school_id, modul) do update set aktif = true;

-- ── 1.3 sc_personal: 150 staf ─────────────────────────────────────────────────────────
-- id ditulis eksplisit (bukan gen_random_uuid()) supaya sc_hasil di bagian 3-4 dan
-- profiles.sc_responden_id di bagian 5 bisa menautnya tanpa query balik.
;
;
